mapper.select:
SELECT sys_material.id, sys_material.type, sys_material.`name`, sys_material.group_id, sys_material.url, sys_material.create_time, sys_material.update_time, sys_material.create_by, sys_material.shop_id, sys_material.update_by, sys_material.del_flag, sys_material.file_size FROM sys_material AS sys_material
AND sys_material.del_flag = '0'
AND sys_material.shop_id=#{query.shopId}
AND sys_material.group_id=#{query.groupId}
AND sys_material.`name` LIKE CANCAT('%',#{query.name},'%')
